jq query: kubectl get services | jq ''.items[] | select(.metadata.namespace=="shop") | {name: .metadata.name, namespace: .metadata.namespace, clusterIP: .spec.clusterIP, ports: .spec.ports}''
{
                    "kind": "services",
                    "jq_expr": ".items[] | select(.metadata.namespace==\"shop\") | {name: .metadata.name, namespace: .metadata.namespace, clusterIP: .spec.clusterIP, ports: .spec.ports}"
                }

jq query: kubectl get endpoints | jq ''.items[] | select(.metadata.namespace=="shop") | {name:.metadata.name, namespace:.metadata.namespace, subsets:.subsets}''
{
                    "kind": "endpoints",
                    "jq_expr": ".items[] | select(.metadata.namespace==\"shop\") | {name:.metadata.name, namespace:.metadata.namespace, subsets:.subsets}"
                }

jq query: kubectl get pods | jq ''.items[] | select(.metadata.namespace=="shop" and .metadata.name=="cache-9ffcf47fc-5d4xf") | {name:.metadata.name, namespace:.metadata.namespace, status:.status.phase, ready:.status.containerStatuses[0].ready, restarts:.status.containerStatuses[0].restartCount, node:.spec.nodeName, podIP:.status.podIP}''
{
