                    "jq_expr": ".items[] | select(.metadata.namespace==\"shop\" and .metadata.name==\"cache-9ffcf47fc-5d4xf\") | {name:.metadata.name, namespace:.metadata.namespace, status:.status.phase, ready:.status.containerStatuses[0].ready, restarts:.status.containerStatuses[0].restartCount, node:.spec.nodeName, podIP:.status.podIP}"
                }

